from collections import Counter

def solution(nums):
    N = len(nums)
    count = Counter(nums)
    ans = 0
    for i in range(N):
        for j in range(N):
            product = nums[i] * nums[j]
            if product in count:
                ans += count[product]

    print(ans)

def main():
    n = int(input().strip())
    solution([int(input().strip()) for _ in range(n)])

if __name__ == "__main__":
    main()
